+                }
+            }
+            parser.feed(b"</longer></r>", true)?;
+            while next_event(&mut parser)?.is_some() {}
+            Ok(())
+        })();
+        parser.finish_adapter_frame(frame);
+        result
+    }
+    check_allocations(workload);
+}
